def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    def is_expired(write_time, current_time):
        return current_time >= write_time + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries from consideration
            expired_keys = [k for k, (_, wt) in cache.items() if is_expired(wt, t)]
            for k in expired_keys:
                del cache[k]

            # If key already exists, remove it (we'll re-add as most recent)
            if key in cache:
                del cache[key]
            # If cache is at capacity and we're adding a new key, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)  # Remove oldest (least recently used)

            # Add/update the key as most recently used
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries from consideration
            expired_keys = [k for k, (_, wt) in cache.items() if is_expired(wt, t)]
            for k in expired_keys:
                del cache[k]

            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

